{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/metric-row.json
    Dashboard counters in a row or a grid: tiles with an icon, a number and a caption, or compact figures. Axes: columns (2, 4), item (tile, compact), tone (default, muted), density (default, compact).
    Props (p): id, title, metrics, empty, cols, item, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_metrics = ($p['metrics'] ?? null)}
{var $v_empty = ($p['empty'] ?? '')}
{var $v_cols = ($p['cols'] ?? '4')}
{var $v_item = ($p['item'] ?? 'tile')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_8}
  {if og_t(og_eq(og_len($v_metrics), 0))}
    {=og_include('blocks/empty-state.latte', ['p' => ['icon' => 'gauge', 'title' => $v_empty]])|noescape}
  {else}
    {capture $c_7}
      {foreach og_l($v_metrics) as $v_m}
        {if og_t(og_eq($v_item, 'tile'))}
          {capture $c_1}
            {=og_include('blocks/stat-tile.latte', ['p' => ['label' => og_get($v_m, ['label']), 'value' => og_get($v_m, ['value']), 'icon' => og_get($v_m, ['icon']), 'hint' => og_get($v_m, ['hint'])]])|noescape}
          {/capture}
          {=og_include('compose/Box.latte', ['attrs' => og_attrs(['data-testid', 'item']), 'children' => (string) $c_1])|noescape}
        {else}
          {capture $c_6}
            {capture $c_3}
              {=og_include('icons/LucideIcon.latte', ['name' => og_s(og_get($v_m, ['icon'])), 'size' => 16])|noescape}
              {capture $c_2}
                {=og_text(og_get($v_m, ['label']))}
              {/capture}
              {=og_include('compose/Text.latte', ['size' => 'xs', 'children' => (string) $c_2])|noescape}
            {/capture}
            {=og_include('compose/Group.latte', ['gap' => '2', 'align' => 'center', 'class' => 'text-muted-foreground', 'children' => (string) $c_3])|noescape}
            {capture $c_4}
              {=og_text(og_get($v_m, ['value']))}
            {/capture}
            {=og_include('compose/Text.latte', ['size' => '2xl', 'weight' => 'bold', 'children' => (string) $c_4])|noescape}
            {capture $c_5}
              {=og_text(og_get($v_m, ['hint']))}
            {/capture}
            {=og_include('compose/Text.latte', ['size' => 'xs', 'class' => 'text-muted-foreground', 'children' => (string) $c_5])|noescape}
          {/capture}
          {=og_include('compose/Stack.latte', ['gap' => '0', 'class' => 'rounded bg-card p-4 inset-ring inset-ring-border', 'attrs' => og_attrs(['data-testid', 'item']), 'children' => (string) $c_6])|noescape}
        {/if}
      {/foreach}
    {/capture}
    {=og_include('compose/Grid.latte', ['cols' => og_s((og_t(og_eq($v_cols, '2')) ? '1-2' : '1-4')), 'class' => 'gap-4', 'attrs' => og_attrs(['data-testid', 'items']), 'children' => (string) $c_7])|noescape}
  {/if}
{/capture}
{=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'density' => $v_density, 'landmarkLabel' => $v_landmarkLabel], 'children' => og_markup($c_8)])|noescape}
